Web Application.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(api_gateway, "API Gateway", "Spring Cloud Gateway / Kong", "External API Gateway handling backend routing")

Container_Boundary(web_application, "Web Application") {
    Component(ui_router_and_views, "UI Router and Views", "React 18, TypeScript, Vite", "Provides page routing and view rendering for self-service portals and the Admin UI.")
    Component(state_management_and_caching, "State Management and Caching", "TanStack Query, Zustand, React Context", "Manages server state, client-side caching, global UI states, roles, and localization to meet performance requirements.")
    Component(http_api_client, "HTTP API Client", "Fetch / Axios", "Communicates securely with the API Gateway via HTTPS/JSON.")
}

Rel(ui_router_and_views, state_management_and_caching, "Reads and writes UI and server state")
Rel(state_management_and_caching, http_api_client, "Triggers data fetching and mutations")
Rel(http_api_client, api_gateway, "Calls backend APIs", "HTTPS/JSON")
@enduml

Core Domain Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Domain Service container

Container_Boundary(core_domain_service, "Core Domain Service") {
    Component(BookItemManagementComponent, "Book/Item Management Component", "Java, Spring Boot, Spring Data JPA", "Manages cataloguing and book/item inventories.")
    Component(CirculationEngineComponent, "Circulation Engine Component", "Java, Spring Boot", "Handles circulation management and processing.")
    Component(DomainEventPublisher, "Domain Event Publisher", "Apache Kafka, Spring Cloud Stream", "Publishes domain events for asynchronous catalogue synchronization.")
    Component(SecurityAuthComponent, "Security/Auth Component", "Spring Security, Java", "Ensures authentication and security controls within the container.")
}

Rel(CirculationEngineComponent, BookItemManagementComponent, "In-process method calls", "Java")

@enduml

PostgreSQL Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(postgresql_database, "PostgreSQL Database") {
    Component(Relational Storage Engine, "Relational Storage Engine", "PostgreSQL container", "Enforces strict EU-only data residency and stores transactional data.")
    Component(PgBouncer Connection Pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages and isolates connection management for database queries.")
    Component(Database Migration Manager, "Database Migration Manager", "Flyway / Liquibase", "Handles schema migrations for the PostgreSQL database.")
}

Rel(PgBouncer Connection Pooler, Relational Storage Engine, "Routes and pools TCP connections")
Rel(Database Migration Manager, Relational Storage Engine, "Applies schema migrations")

@enduml
